// Before: nesting, and errors handled by hand
func loadProfile(completion: @escaping (Result<Profile, Error>) -> Void) {
    fetchUser { result in
        switch result {
        case .success(let user):
            fetchAvatar(user.id) { avatarResult in
                // ...and so on
            }
        case .failure(let error): completion(.failure(error))
        }
    }
}

// After: sequential, with ordinary error handling
func loadProfile() async throws -> Profile {
    let user   = try await fetchUser()
    let avatar = try await fetchAvatar(user.id)
    return Profile(user: user, avatar: avatar)
}

// Independent work should actually overlap
func loadProfileConcurrently() async throws -> Profile {
    async let user   = fetchUser()
    async let banner = fetchBanner()
    return try await Profile(user: user, banner: banner)
}

actor ScoreBoard {
    private var scores: [String: Int] = [:]

    func record(_ points: Int, for player: String) {
        scores[player, default: 0] += points     // inside: direct, synchronous
    }

    func score(for player: String) -> Int {
        scores[player] ?? 0
    }

    nonisolated let boardID = UUID()             // immutable: no protection needed
}

let board = ScoreBoard()
await board.record(10, for: "ada")               // outside: must await
let total = await board.score(for: "ada")
_ = board.boardID                                // nonisolated: no await

actor ImageCache {
    private var cache: [URL: Image] = [:]
    private var inFlight: [URL: Task<Image, Error>] = [:]

    func image(at url: URL) async throws -> Image {
        if let cached = cache[url] { return cached }
        if let existing = inFlight[url] { return try await existing.value }  // dedupe

        let task = Task { try await download(url) }
        inFlight[url] = task
        defer { inFlight[url] = nil }

        let image = try await task.value
        cache[url] = image
        return image
    }

    private func download(_ url: URL) async throws -> Image { fatalError("…") }
}

@MainActor
final class ProfileViewModel {
    var name = ""            // main-actor isolated
    var isLoading = false

    func load() async {
        isLoading = true
        // hop off to do the slow part
        let profile = await ProfileLoader().fetch()   // not main-actor isolated
        // back on the main actor automatically after the await
        name = profile.name
        isLoading = false
    }
}

// Not main-actor bound: free to run on the cooperative pool
struct ProfileLoader {
    nonisolated func fetch() async -> Profile { … }
}

// Marking one function rather than a whole type
@MainActor func present(_ alert: Alert) { … }

// Automatically Sendable: a struct of Sendable parts
struct Score: Sendable { let player: String; let points: Int }

// Not Sendable: a class with mutable state, freely shareable
final class Counter { var value = 0 }

// Safe to share: immutable, and final so nobody adds mutable state
final class Config: Sendable { let baseURL: URL; init(_ u: URL) { baseURL = u } }

// Safe because *you* guarantee it — the compiler stops checking here
final class LockedCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var _value = 0
    var value: Int { lock.withLock { _value } }
    func increment() { lock.withLock { _value += 1 } }
}

// An actor is always Sendable: its state is protected by construction
actor Tally { private var total = 0 }
